bin/git.text:
#!/bin/sh
d=$(dirname "$0")
echo "$*" >> "$d/git.log"
case "$*" in
  *'symbolic-ref -q refs/remotes/origin/HEAD') printf '%s' 'refs/remotes/origin/trunk
'; exit 0;;
  *'rev-parse --verify -q refs/remotes/origin/trunk^{commit}') exit 0;;
  *) exit 1;;
esac

